# EVOLVE-BLOCK-START
import networkx as nx
import json
import os
import pandas as pd
from typing import Dict, List


def search_algorithm(src, dsts, G, num_partitions):
    """Assign bounded shortest-simple-path alternatives per partition.

    Candidate routes are cost-first paths with a small low-throughput penalty.
    Assignments share already used broadcast links when possible, but divert a
    partition when its projected edge load would exceed available throughput.
    Choices are lexicographically ordered by overload, added link cost, and
    hop count.
    """
    import math
    from itertools import islice

    topology = BroadCastTopology(src, dsts, num_partitions)
    h = G.copy()
    h.remove_edges_from(list(h.in_edges(src)) + list(nx.selfloop_edges(h)))
    h.remove_edges_from([
        (u, v) for u, v, data in h.edges(data=True)
        if data.get("cost") is None
        or not math.isfinite(float(data["cost"]))
        or float(data["cost"]) < 0
    ])

    terminals = list(dict.fromkeys(dst for dst in dsts if dst != src))
    candidates = {}
    max_candidates = 8

    def path_weight(u, v, data):
        throughput = float(data.get("throughput", 0) or 0)
        # Invalid capacity is not removed: it remains a last-resort route for
        # otherwise disconnected inputs, but is strongly disfavored.
        return float(data["cost"]) + 1e-6 / max(throughput, 1e-12)

    for dst in terminals:
        if src not in h or dst not in h:
            candidates[dst] = []
            continue
        try:
            paths = islice(
                nx.shortest_simple_paths(h, src, dst, weight=path_weight),
                max_candidates,
            )
            candidates[dst] = [list(zip(path, path[1:])) for path in paths]
        except (nx.NetworkXNoPath, nx.NodeNotFound):
            candidates[dst] = []

    # A partition represents an equal share of one input.  A shared edge used
    # by the same partition for several destinations is counted only once,
    # matching broadcast replication at a relay.
    demand = 1.0 / max(1, num_partitions)
    edge_load = {}
    edge_partitions = {}
    active_edges = set()
    selected = {}

    for partition in range(num_partitions):
        for dst in terminals:
            options = candidates.get(dst, [])
            if not options:
                selected[(dst, partition)] = []
                continue

            def score(path):
                overload_count = 0
                overload_amount = 0.0
                added_cost = 0.0
                for edge in path:
                    data = h[edge[0]][edge[1]]
                    seen = partition in edge_partitions.get(edge, set())
                    projected = edge_load.get(edge, 0.0) + (0.0 if seen else demand)
                    capacity = float(data.get("throughput", 0) or 0)
                    if projected > capacity:
                        overload_count += 1
                        overload_amount += projected - capacity
                    if edge not in active_edges:
                        added_cost += float(data["cost"])
                return (overload_count, overload_amount, added_cost, len(path))

            path = min(options, key=score)
            selected[(dst, partition)] = path
            for edge in path:
                users = edge_partitions.setdefault(edge, set())
                if partition not in users:
                    users.add(partition)
                    edge_load[edge] = edge_load.get(edge, 0.0) + demand
                active_edges.add(edge)

    for dst in dsts:
        for partition in range(num_partitions):
            if dst == src:
                route = []
            else:
                route = [
                    [u, v, G[u][v]]
                    for u, v in selected.get((dst, partition), [])
                ]
            topology.set_dst_partition_paths(dst, partition, route)

    return topology


class SingleDstPath(Dict):
    partition: int
    edges: List[List]  # [[src, dst, edge data]]


class BroadCastTopology:
    def __init__(self, src: str, dsts: List[str], num_partitions: int = 4, paths: Dict[str, SingleDstPath] = None):
        self.src = src  # single str
        self.dsts = dsts  # list of strs
        self.num_partitions = num_partitions

        # dict(dst) --> dict(partition) --> list(nx.edges)
        # example: {dst1: {partition1: [src->node1, node1->dst1], partition 2: [src->dst1]}}
        if paths is not None:
            self.paths = paths
            self.set_graph()
        else:
            self.paths = {dst: {str(i): None for i in range(num_partitions)} for dst in dsts}

    def get_paths(self):
        print(f"now the set path is: {self.paths}")
        return self.paths

    def set_num_partitions(self, num_partitions: int):
        self.num_partitions = num_partitions

    def set_dst_partition_paths(self, dst: str, partition: int, paths: List[List]):
        """
        Set paths for partition = partition to reach dst
        """
        partition = str(partition)
        self.paths[dst][partition] = paths

    def append_dst_partition_path(self, dst: str, partition: int, path: List):
        """
        Append path for partition = partition to reach dst
        """
        partition = str(partition)
        if self.paths[dst][partition] is None:
            self.paths[dst][partition] = []
        self.paths[dst][partition].append(path)

def make_nx_graph(cost_path=None, throughput_path=None, num_vms=1):
    """
    Default graph with capacity constraints and cost info
    nodes: regions, edges: links
    per edge:
        throughput: max tput achievable (gbps)
        cost: $/GB
        flow: actual flow (gbps), must be < throughput, default = 0
    """
    # Use relative path from this file's location
    current_dir = os.path.dirname(os.path.abspath(__file__))

    if cost_path is None:
        cost = pd.read_csv(os.path.join(current_dir, "profiles/cost.csv"))
    else:
        cost = pd.read_csv(cost_path)

    if throughput_path is None:
        throughput = pd.read_csv(os.path.join(current_dir, "profiles/throughput.csv"))
    else:
        throughput = pd.read_csv(throughput_path)

    G = nx.DiGraph()
    for _, row in throughput.iterrows():
        if row["src_region"] == row["dst_region"]:
            continue
        G.add_edge(row["src_region"], row["dst_region"], cost=None, throughput=num_vms * row["throughput_sent"] / 1e9)

    for _, row in cost.iterrows():
        if row["src"] in G and row["dest"] in G[row["src"]]:
            G[row["src"]][row["dest"]]["cost"] = row["cost"]

    # some pairs not in the cost grid
    no_cost_pairs = []
    for edge in G.edges.data():
        src, dst = edge[0], edge[1]
        if edge[-1]["cost"] is None:
            no_cost_pairs.append((src, dst))
    print("Unable to get costs for: ", no_cost_pairs)

    return G


